class sos32_membertitle extends skin_ucp(~id~)
{
	public function membersProfileForm( $custom_fields='',$group_titles='',$day='',$mon='',$year='', $amEditor='', $times=array() )
	{
		$temp = $this->settings['post_titlechange'];
		$this->settings['post_titlechange'] = false;

		$original = parent::membersProfileForm( $custom_fields,$group_titles,$day,$mon,$year,$amEditor, $times );

	    $this->settings['post_titlechange'] = $temp;

	    return $original;
	}
}

